contract InvMutTest {
    C c;
    address origOwner;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe before-values
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 beforeCbal = address(c).balance;

        bool reverted;
        // top-level state-changing call
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 afterCbal = address(c).balance;

        // General rule:
        // - owner never changes
        // - if call succeeds, C's balance after is <= amount (it should forward out at least the sent value so it doesn't retain more than was sent)
        // - if call reverts, no requirement on balance (call didn't complete)
        assert(
            afterOwner == beforeOwner
            && (reverted ? true : afterCbal <= amount)
        );
    }
    receive() external payable { }
}

